INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Modularisierung nur für große Projekte sinnvoll?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte profitieren von Wiederverwendung"}, {"text": "Ja", "correct": false, "because": "Größe ist nicht entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Modularisierung?', 3, '[{"text": "Wiederverwendbarkeit erhöhen", "correct": true, "because": "Module sind unabhängig nutzbar"}, {"text": "Code schneller schreiben", "correct": false, "because": "Planung braucht Zeit"}, {"text": "Speicher sparen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Modularisierung?', 5, '[{"text": "Wartbarkeit", "correct": true, "because": "Module einzeln anpassbar"}, {"text": "Testbarkeit", "correct": true, "because": "Isolierte Tests möglich"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Weniger Variablen", "correct": false, "because": "Unabhängig davon"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Modularisierung trennt Funktionen. b) Sie erhöht immer die Performance.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Performance nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Modularisierung?', 4, '[{"text": "Abhängigkeiten", "correct": false, "because": "Müssen minimiert werden"}, {"text": "Schnittstellen", "correct": false, "because": "Definiert Interaktion"}, {"text": "Farbcodierung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Modularisierung mehr Planung braucht?', 2, '[{"text": "Ja", "correct": true, "because": "Struktur muss durchdacht sein"}, {"text": "Nein", "correct": false, "because": "Spontanität schadet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip unterstützt Modularisierung am besten?', 3, '[{"text": "Single Responsibility", "correct": true, "because": "Eine Aufgabe pro Modul"}, {"text": "Open Closed", "correct": false, "because": "Erweiterungsfokus"}, {"text": "KISS", "correct": false, "because": "Eher allgemein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei Modularisierung entscheidend?', 5, '[{"text": "Klare Schnittstellen", "correct": true, "because": "Definiert Interaktion"}, {"text": "Unabhängigkeit", "correct": true, "because": "Minimiert Kopplung"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Kein direkter Faktor"}, {"text": "Maximale Zeilen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Modularisierung spart Zeit. b) Sie macht Code immer kürzer. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kürze nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Modularisierung?', 4, '[{"text": "Kapselung", "correct": false, "because": "Schützt Module"}, {"text": "Schnittstellen", "correct": false, "because": "Verbindet Module"}, {"text": "Grafische Oberfläche", "correct": true, "because": "Kein Code-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Modularisierung ohne Kapselung möglich?', 2, '[{"text": "Ja", "correct": true, "because": "Kapselung unterstützt nur"}, {"text": "Nein", "correct": false, "because": "Nicht zwingend nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften fördert Modularisierung?', 4, '[{"text": "Wiederverwendbarkeit", "correct": true, "because": "Module unabhängig nutzbar"}, {"text": "Lesbarkeit", "correct": true, "because": "Klare Trennung"}, {"text": "Schnellere Kompilierung", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Modularisierung nur für Teams ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Solo profitabel"}, {"text": "Ja", "correct": false, "because": "Einzelnutzen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Modularisierung?', 3, '[{"text": "Lose Kopplung", "correct": true, "because": "Minimiert Abhängigkeiten"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Qualität zählt"}, {"text": "Viele Funktionen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Modularisierung reduziert Komplexität. b) Sie ersetzt Unittests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tests bleiben nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat Modularisierung?', 5, '[{"text": "Höherer Planungsaufwand", "correct": true, "because": "Struktur braucht Zeit"}, {"text": "Komplexere Schnittstellen", "correct": true, "because": "Interaktion definieren"}, {"text": "Langsamere Ausführung", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Modularisierung unwichtig?', 3, '[{"text": "Kapselung", "correct": false, "because": "Schützt Module"}, {"text": "Unabhängigkeit", "correct": false, "because": "Kernprinzip"}, {"text": "UI-Design", "correct": true, "because": "Kein Code-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht Modularisierung die Zeilenanzahl?', 3, '[{"text": "Ja", "correct": true, "because": "Schnittstellen erhöhen Code"}, {"text": "Nein", "correct": false, "because": "Kann auch kürzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Modularisierung Debugging erleichtert?', 2, '[{"text": "Ja", "correct": true, "because": "Isolierte Module leichter prüfbar"}, {"text": "Nein", "correct": false, "because": "Trennung hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt Modularisierung?', 4, '[{"text": "Dependency Injection", "correct": true, "because": "Lose Kopplung fördern"}, {"text": "Compiler-Optimierung", "correct": false, "because": "Anderer Fokus"}, {"text": "UI-Framework", "correct": false, "because": "Nicht codezentriert"}]');
